INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-roots', 'down', 'the-root-hang', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ward-ditch', 'down', 'the-ditch-sink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-buckled-ground', 'down', 'the-heave', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-mire', 'down', 'the-spring-throat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ridge-cave', 'down', 'the-bears-stair', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferny-bank', 'down', 'the-fern-hole', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-root-hang', 'door', 'The Root Hang', 'The roots of the Under-Roots come down through a split in the rock and hang into the dark below it, a tangle of them as thick as your arm, earth still on them. You climb down them as you would a ladder. The floor is stone, and the air coming past you goes up the way you came, cold on the back of your neck.', 0, 0, 'cave', 0, -36, -1, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hang', 'up', 'the-under-roots', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hang', 'west', 'the-root-curtain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-hang', 'south', 'the-taproot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-root-curtain', 'door', 'The Root Curtain', 'Fine roots hang from the roof to the floor in a curtain, hundreds of them, white and soft and finer than hair at the tips. They move. There is no wind you can feel, but they lean all one way, toward the roof, and settle back, and lean again.', 0, 0, 'cave', 0, -37, -1, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-curtain', 'east', 'the-root-hang', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-curtain', 'west', 'the-rat-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ditch-sink', 'door', 'The Ditch Sink', 'The water at the bottom of the ditch above finds a hole in the rock and comes down through it here in a thin green fall, and you come down with it, on a slope of slime and stones. What light the ditch has comes down the hole after you and lies on the wet. The water runs away south along the floor into the dark.', 0, 0, 'cave', 0, -39, -9, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ditch-sink', 'up', 'the-ward-ditch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ditch-sink', 'south', 'the-ditch-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ditch-water', 'door', 'The Ditch Water', 'The ditch''s water runs along the floor here in a shallow stream, green with the stuff it brings down from above, over a bed of rotten leaves and the things that fell into the ditch and were carried down: a bone, a buckle, the iron head of an arrow. The cold air goes the other way, up past you toward the hole.', 0, 0, 'cave', 0, -39, -8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ditch-water', 'north', 'the-ditch-sink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ditch-water', 'south', 'the-silted-pipe', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-silted-pipe', 'door', 'The Silted Pipe', 'A round pipe of rock, smooth as a drain, worn by water that ran full in it once, and now half-filled with grey silt the stream has dropped. You go along the top of the silt bent double. The silt holds the prints of something that came this way on four feet and went back.', 0, 0, 'cave', 0, -39, -7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silted-pipe', 'north', 'the-ditch-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silted-pipe', 'south', 'the-wind-crawl', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wind-crawl', 'door', 'The Wind Crawl', 'The pipe pinches to a crawl and the air comes through it hard from the south, cold, into your face, so that you crawl against it with your eyes half shut. It never slackens. Whatever is breathing out down there has a long breath.', 0, 0, 'cave', 0, -39, -6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-crawl', 'north', 'the-silted-pipe', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wind-crawl', 'south', 'the-pawed-sand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pawed-sand', 'door', 'The Pawed Sand', 'A little chamber floored with dry sand, and the sand pawed over and over by feet with long claws and no pads, round and round in circles, as if something had stood here a long while turning its head to listen. The circles are fresh on top of old ones.', 0, 0, 'cave', 0, -39, -5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pawed-sand', 'north', 'the-wind-crawl', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pawed-sand', 'south', 'the-breakdown', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-breakdown', 'door', 'The Breakdown', 'The roof of a chamber came down here long ago in blocks the size of carts, and the way on goes through the heap of them, over and under, in gaps between blocks that lean on each other. Some of them have moved since they fell. You can see where.', 0, 0, 'cave', 0, -39, -4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-breakdown', 'north', 'the-pawed-sand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-breakdown', 'south', 'the-north-squeeze', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-north-squeeze', 'door', 'The North Squeeze', 'A squeeze between two walls of rock that lean together overhead, so narrow you go through with your arms in front of you and your head turned. The rock is polished at the height of your hips by many bodies going through low and fast. Yours is not one of them.', 0, 0, 'cave', 0, -39, -3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-squeeze', 'north', 'the-breakdown', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-squeeze', 'south', 'the-dripping-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dripping-ledge', 'door', 'The Dripping Ledge', 'A ledge over a short drop, with water dripping onto it from the roof in a steady patter and running off its edge. Below the ledge the passage turns east, and there is a sour smell of burrows.', 0, 0, 'cave', 0, -39, -2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dripping-ledge', 'north', 'the-north-squeeze', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dripping-ledge', 'east', 'the-rat-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rat-run', 'door', 'The Burrow Run', 'A low run of rock going south toward the shelf where the grubbets dig, its floor black and greasy and printed thick with small splayed feet, and the soft rock at the foot of the walls scraped out by claws. Little bones crunch underfoot. Every hole in the wall has a snout in it.', 0, 0, 'cave', 0, -38, -2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rat-run', 'west', 'the-dripping-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rat-run', 'south', 'the-rat-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rat-shelf', 'door', 'The Burrow Shelf', 'A shelf of rock along one wall at the height of your knee, its edge black and greasy with the passing of fat small bodies. The floor under it is droppings and the husks of things, and burrows go back into the soft rock under the shelf, each as wide as a rabbit''s, too many to count.', 0, 0, 'cave', 0, -38, -1, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rat-shelf', 'east', 'the-root-curtain', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rat-shelf', 'north', 'the-rat-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rat-shelf', 'south', 'the-gnawed-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-gnawed-floor', 'door', 'The Gnawed Floor', 'Bones lie about the floor here, small ones and some not small, and every one of them has been gone over by teeth too small to crack it, the ends scored fine as a file would score them. Nothing has been left on them. Nothing has been left at all.', 0, 0, 'cave', 0, -38, 0, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-floor', 'north', 'the-rat-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnawed-floor', 'south', 'the-four-ways', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-taproot', 'door', 'The Taproot', 'One root comes down out of the roof here that is not like the others: a single taproot, as thick as a man, going straight down through a hole in the floor that it has made for itself in the rock. Cold air comes up round it out of the hole, steady as breath, and you cannot see how far it goes.', 0, 0, 'cave', 0, -36, 0, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-taproot', 'north', 'the-root-hang', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-taproot', 'south', 'the-drip-stones', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-drip-stones', 'door', 'The Drip Stones', 'Water comes through the roof here a drop at a time and has been coming a long while: thin stone straws hang down from the roof where it drips, and fat stumps of stone have grown up off the floor to meet them. Some have met. The drops fall all round you in no rhythm you can follow.', 0, 0, 'cave', 0, -36, 1, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drip-stones', 'north', 'the-taproot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drip-stones', 'west', 'the-cold-draught', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drip-stones', 'south', 'the-root-chimney', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-draught', 'door', 'The Cold Draught', 'The passage pinches here to the width of your shoulders and the air comes through the gap hard, cold enough to make your eyes water, out of the lower ground and away up toward the roots. Anything light you hold out flutters toward the roof.', 0, 0, 'cave', 0, -37, 1, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-draught', 'east', 'the-drip-stones', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-draught', 'west', 'the-four-ways', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-four-ways', 'door', 'The Four Ways', 'Four passages meet in a low round room with a floor worn into a shallow bowl. All four look the same: round, dark, the height of a stooping man. Only one of them has the cold air coming out of it.', 0, 0, 'cave', 0, -38, 1, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-four-ways', 'north', 'the-gnawed-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-four-ways', 'east', 'the-cold-draught', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-four-ways', 'south', 'the-scored-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-root-chimney', 'door', 'The Root Chimney', 'The last of the roots go down here into a chimney in the floor, a round shaft polished by water long gone, and the roots go down it too, far past where any tree could reach, holding to the rock all the way down. They are the only way to climb it. The air comes up it cold and does not stop.', 0, 0, 'cave', 0, -36, 2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-chimney', 'north', 'the-drip-stones', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-chimney', 'south', 'the-clay-slide', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-chimney', 'down', 'the-ladder-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-scored-wall', 'door', 'The Scored Wall', 'The walls here are scored at knee height, both sides, all along the passage: shallow scratches in their hundreds, the marks of something low passing close to the rock and touching it as it goes. Something that feels its way. The scratches go on into the dark ahead.', 0, 0, 'cave', 0, -38, 2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scored-wall', 'north', 'the-four-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scored-wall', 'south', 'the-blind-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-blind-turn', 'door', 'The Blind Turn', 'The passage turns back on itself here so hard you cannot see one leg of it from the other. Sound does strange things at the corner. Your own steps come back to you a beat late, from the wrong side, and then do not stop when you stop.', 0, 0, 'cave', 0, -38, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blind-turn', 'north', 'the-scored-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blind-turn', 'east', 'the-echo-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blind-turn', 'south', 'the-sounding-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blind-turn', 'west', 'the-narrow-neck', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-clay-slide', 'door', 'The Clay Slide', 'A bank of wet clay runs down from the chimney''s foot, slick and grey, and you go down it on your heels whether you mean to or not. The clay keeps prints. There are a great many prints in it, of feet with long claws and no sign of a pad that hesitated.', 0, 0, 'cave', 0, -36, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clay-slide', 'north', 'the-root-chimney', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clay-slide', 'west', 'the-echo-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-clay-slide', 'south', 'the-bone-spill', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-echo-gallery', 'door', 'The Echo Gallery', 'A long gallery with a high arched roof, smooth as the inside of a horn. A word spoken here runs away along it and comes back from both ends, and any sound at all hangs in it for a long time. Anything listening could hear you from a long way off.', 0, 0, 'cave', 0, -37, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-echo-gallery', 'west', 'the-blind-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-echo-gallery', 'east', 'the-clay-slide', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bone-spill', 'door', 'The Bone Spill', 'Bones spill out of a side passage across the floor here like a load tipped off a cart: deer legs, a boar''s jaw, the long bones of something the size of a man. They have been cracked for the marrow by teeth bigger than a dog''s. The smell of the passage they came out of is thick and sour.', 0, 0, 'cave', 0, -36, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-spill', 'north', 'the-clay-slide', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-spill', 'east', 'the-hounds-bed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-spill', 'south', 'the-rattling-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hounds-bed', 'door', 'The Hounds'' Bed', 'A low chamber at the end of the side passage, its floor trodden into hollows the size of a curled dog, four or five of them, warm with use. Grey hair is matted into the dust. It is a place to sleep, and nothing that sleeps here needs a light to find it.', 0, 0, 'cave', 0, -35, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hounds-bed', 'west', 'the-bone-spill', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rattling-way', 'door', 'The Rattling Way', 'Loose plates of stone cover the floor here, thin as slates, and they shift and clatter under every step however you put your feet down. There is no quiet way across. Somewhere off in the dark the clatter is answered, once, by something moving.', 0, 0, 'cave', 0, -36, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rattling-way', 'north', 'the-bone-spill', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rattling-way', 'west', 'the-loose-stones', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-loose-stones', 'door', 'The Loose Stones', 'The roof has been shedding stone here, a little at a time, and the floor is a slope of it, broken and sharp. Some of it is newer than the rest, pale at the edges where it split. You look up. The roof looks the same as the roof anywhere else.', 0, 0, 'cave', 0, -37, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-stones', 'east', 'the-rattling-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-loose-stones', 'west', 'the-shale-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sounding-room', 'door', 'The Sounding Room', 'A round chamber with a dome of smooth rock, where every sound gathers in the middle and stays. A drop of water falling sounds like a stone. Your breathing sounds like someone else''s, close beside you. Standing still is the only way to hear anything that is not you.', 0, 0, 'cave', 0, -38, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sounding-room', 'north', 'the-blind-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sounding-room', 'south', 'the-shale-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shale-floor', 'door', 'The Shale Floor', 'Thin grey shale underfoot, broken into flakes that crunch like frost. A track has been worn down the middle of it by many feet, all going the same few ways, all low to the ground, and none of them stopped to look about. They knew where they were going without looking.', 0, 0, 'cave', 0, -38, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shale-floor', 'east', 'the-loose-stones', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shale-floor', 'north', 'the-sounding-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shale-floor', 'south', 'the-sand-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sand-floor', 'door', 'The Sand Floor', 'Dry sand, fine and pale, laid down by water that has been gone a very long time. It holds every mark: the scored lines of claws, a drag where something heavy was pulled across it, and your own feet, very loud in it, very easy to follow.', 0, 0, 'cave', 0, -38, 6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sand-floor', 'north', 'the-shale-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sand-floor', 'south', 'the-bat-chimney', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bat-chimney', 'door', 'The Bat Chimney', 'A chimney opens in the floor here, a ragged shaft going down, and the rock all round its lip is black and slick and the floor deep in droppings that smell of ammonia. The air coming up it is warmer than the cave''s and carries a thin high chittering, very far down, from a great many throats.', 0, 0, 'cave', 0, -38, 7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bat-chimney', 'north', 'the-sand-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bat-chimney', 'west', 'the-gnaw-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bat-chimney', 'down', 'the-roost-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-gnaw-hole', 'door', 'The Gnaw Hole', 'A low hole in the side of the passage, with a fan of chewed scraps spread out from its mouth: hide, gristle, a hoof, the tip of an ear. Small eyes catch what light there is from back inside it and are gone.', 0, 0, 'cave', 0, -39, 7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnaw-hole', 'east', 'the-bat-chimney', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gnaw-hole', 'south', 'the-cougars-larder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-narrow-neck', 'door', 'The Narrow Neck', 'The passage closes to a slot you turn sideways to pass, the rock pressing your chest and back. On the far side the walls fall away all at once and the air changes: wider, colder, moving, the feel of a great deal of empty dark ahead.', 0, 0, 'cave', 0, -39, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-narrow-neck', 'east', 'the-blind-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-narrow-neck', 'west', 'the-lip', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-lip', 'door', 'The Lip', 'You come out on a lip of rock high in the wall of a chamber too big for any light to cross. Below is a long fall of scree going down into the dark. A thin ledge runs off along the wall to one side, and the way down is the scree or nothing.', 0, 0, 'cave', 0, -40, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lip', 'east', 'the-narrow-neck', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lip', 'west', 'the-overhang', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lip', 'south', 'the-scree-slope', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-overhang', 'door', 'The Overhang', 'The ledge goes under an overhang here and you go along it bent, the roof at your back and the drop at your elbow. The ledge is wide enough for a person and no more. It is wide enough for an animal that lies flat and waits, and the dust on it is lain in.', 0, 0, 'cave', 0, -41, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-overhang', 'east', 'the-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-overhang', 'west', 'the-thin-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-thin-ledge', 'door', 'The Thin Ledge', 'The ledge narrows to a foot''s width with the chamber below it. Long scratches run down the rock from the ledge''s edge into the dark, in fours, as if something had gone over it and down the wall on purpose, many times. Below, out of sight, something has fallen with a crack, or landed.', 0, 0, 'cave', 0, -42, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-ledge', 'east', 'the-overhang', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-ledge', 'west', 'the-cats-lie', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thin-ledge', 'south', 'the-fallen-slab', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cats-lie', 'door', 'The Cat''s Lie', 'The ledge ends in a hollow in the wall, dry, out of the draught, with a view down over the whole floor of the chamber for anything that could see in the dark. The floor of the hollow is padded with shed fur, tawny and short, and the stone is warm under your hand.', 0, 0, 'cave', 0, -43, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cats-lie', 'east', 'the-thin-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-scree-slope', 'door', 'The Scree Slope', 'A long slope of loose scree going down from the lip to the chamber floor, every stone of it ready to go. You go down it in a slide of rattling stone that does not stop when you do and runs on below you into the dark. Everything down there knows you are coming.', 0, 0, 'cave', 0, -40, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-slope', 'north', 'the-lip', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scree-slope', 'west', 'the-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hollow', 'door', 'The Hollow', 'The floor of the great chamber. The roof is out of sight and the walls are out of sight and the dark goes off in every direction. The air moves here as it moves nowhere else, a slow cold river of it rising past you toward a roof you cannot see. Ledges run along the walls above, where you cannot see them either.', 0, 0, 'cave', 0, -41, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow', 'east', 'the-scree-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow', 'west', 'the-fallen-slab', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollow', 'south', 'the-under-ledge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-fallen-slab', 'door', 'The Fallen Slab', 'A slab of the roof as big as a house lies broken on the chamber floor, fallen a long time ago, its top grown over with stone. It leans against the wall, and between them there is a gap you can climb up toward the ledges. Above you, on the wall, there is a fresh pale scar.', 0, 0, 'cave', 0, -42, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-slab', 'north', 'the-thin-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-slab', 'east', 'the-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-slab', 'south', 'the-hollows-throat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-under-ledge', 'door', 'The Under-Ledge', 'The chamber floor runs in under a long ledge that juts from the wall overhead, and you walk with the rock low over you and the open dark on your other side. Old bones lie half under the ledge, a roe''s ribs and legs picked white, as if they had been dropped from above.', 0, 0, 'cave', 0, -41, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-ledge', 'north', 'the-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-ledge', 'west', 'the-hollows-throat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-ledge', 'south', 'the-cold-well', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hollows-throat', 'door', 'The Hollow''s Throat', 'The chamber narrows at its west end into a throat of rock, and all the air in the great hollow seems to come from the west and go out up past you. Fine dust lifts off the floor and drifts upward and does not come down.', 0, 0, 'cave', 0, -42, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollows-throat', 'north', 'the-fallen-slab', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollows-throat', 'east', 'the-under-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hollows-throat', 'west', 'the-west-gallery', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-well', 'door', 'The Cold Well', 'A round well in the chamber floor, black, the edge of it smooth, and the cold coming up out of it hard enough to lift your hair. Drop a stone and you hear it for a long time. There are handholds worn in the rock going down, made by nothing but the shape of the rock and a great many hands.', 0, 0, 'cave', 0, -41, 6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-well', 'north', 'the-under-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-well', 'south', 'the-split-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-well', 'down', 'the-well-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-split-floor', 'door', 'The Split Floor', 'The floor here has split along its length, a crack a stride wide running away ahead of you with the dark going down in it. You walk with a foot on each side. Air comes up out of the crack all along it, cold, and smells of wet stone a long way down.', 0, 0, 'cave', 0, -41, 7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-split-floor', 'north', 'the-cold-well', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-split-floor', 'south', 'the-rubble-slope', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rubble-slope', 'door', 'The Rubble Slope', 'Earth and broken stone have come down through the roof here and spread in a slope across the passage: soil, stones, roots, a whole tree''s worth of root mass, still moist. The wood has come into the cave. Something has been dragged down the slope through it, often.', 0, 0, 'cave', 0, -41, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rubble-slope', 'north', 'the-split-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rubble-slope', 'east', 'the-drag-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rubble-slope', 'west', 'the-root-fall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-drag-way', 'door', 'The Drag Way', 'A smooth groove runs along the floor here, worn by something heavy pulled along it again and again, and the stone on either side is spotted with old dark stains. Tufts of red-brown deer hair are caught on the rough places. The groove goes one way: in.', 0, 0, 'cave', 0, -40, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-way', 'west', 'the-rubble-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drag-way', 'east', 'the-cougars-larder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cougars-larder', 'door', 'The Cougar''s Larder', 'A dead end where the drag way stops, the floor heaped with the bones of what was dragged down it: roe and young boar, ribs and skulls, a fawn''s legs, scraps of dry hide, every neck bitten through. Some of it is old. Some of it is not. Small things have been at all of it.', 0, 0, 'cave', 0, -39, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cougars-larder', 'north', 'the-gnaw-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cougars-larder', 'west', 'the-drag-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-root-fall', 'door', 'The Root Fall', 'Tree roots hang through a broken roof here in a curtain, with soil still sifting down through them, and through the gap above them comes a little of whatever light is in the wood. Enough to see the roots by. The cave floor is green with moss where it reaches and black beyond.', 0, 0, 'cave', 0, -42, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-fall', 'east', 'the-rubble-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-fall', 'west', 'the-heave', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-heave', 'door', 'The Heave', 'The roots of the Buckled Ground heaved the floor of the wood up until it broke, and here is where it broke through: a ragged hole overhead with roots across it and whatever light the wood has coming down past them, and a slope of fallen earth to climb. The cave goes off from the foot of the slope in three directions into the dark.', 0, 0, 'cave', 0, -43, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heave', 'east', 'the-root-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heave', 'up', 'the-buckled-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heave', 'north', 'the-curtains', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heave', 'south', 'the-break-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-break-pool', 'door', 'The Break Pool', 'Rain that comes in through the break above runs down here and lies in a clear shallow pool on the cave floor, so still you can see every stone in the bottom of it. Animal tracks go to its edge from every side. Whatever light comes in at the break reaches it, and goes no further.', 0, 0, 'cave', 0, -43, 9, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-break-pool', 'north', 'the-heave', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-break-pool', 'south', 'the-wet-passage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wet-passage', 'door', 'The Wet Passage', 'Water runs down the walls here in sheets and over the floor in a film you splash through. It is all going one way, away from the break, and it is louder than it should be. Under the noise of it, from somewhere ahead and below, comes the sound of more water.', 0, 0, 'cave', 0, -43, 10, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-passage', 'north', 'the-break-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-passage', 'south', 'the-weeping-crawl', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-weeping-crawl', 'door', 'The Weeping Crawl', 'The roof comes down and you go on hands and knees through cold water, the rock weeping on your back, the passage climbing. Ahead there is a sound of water welling up.', 0, 0, 'cave', 0, -43, 11, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weeping-crawl', 'north', 'the-wet-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weeping-crawl', 'south', 'the-spring-throat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-spring-throat', 'door', 'The Spring''s Throat', 'The spring of the Spring Mire comes up here from below: a round throat in the rock full of water rising, cold enough to stop your breath, welling up and spilling over and running away up a crawl toward the mire. Down the throat, under the water, the rock goes on down, and the water is coming from somewhere.', 0, 0, 'cave', 0, -43, 12, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-throat', 'north', 'the-weeping-crawl', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-throat', 'up', 'the-spring-mire', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-throat', 'down', 'the-spring-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-west-gallery', 'door', 'The West Gallery', 'A broad gallery running west, its floor flat and its roof low and even, as if the rock were laid in beds and the water took out one of them. The draught runs along it toward the hollow at your back, steady, smelling of wet stone.', 0, 0, 'cave', 0, -43, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-gallery', 'east', 'the-hollows-throat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-gallery', 'west', 'the-rimstone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-gallery', 'south', 'the-flowstone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rimstone', 'door', 'The Rimstone', 'The floor is built up into steps of stone basins, rim over rim, each lipped with a wall of stone no higher than your ankle, each dry and floored with dust. The water that made them is gone. You step from basin to basin.', 0, 0, 'cave', 0, -44, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rimstone', 'east', 'the-west-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rimstone', 'west', 'the-calcite-crawl', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-calcite-crawl', 'door', 'The Calcite Crawl', 'A low crawl lined with white crystal, every face of it glittering at any light you bring and leaping with it, so the passage seems to move as you move. Fur is caught on the sharp crystals here and there, tawny and short, at the height of a crawling back.', 0, 0, 'cave', 0, -45, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-calcite-crawl', 'east', 'the-rimstone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-calcite-crawl', 'west', 'the-narrows', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-flowstone', 'door', 'The Flowstone', 'A wall of stone that looks as if it were poured: smooth, rippled, folded over on itself, the colour of old honey, running down from the roof to the floor as if it had been flowing yesterday and stopped. Your hand on it comes away dry.', 0, 0, 'cave', 0, -43, 6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flowstone', 'north', 'the-west-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-flowstone', 'south', 'the-curtains', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-curtains', 'door', 'The Curtains', 'Thin sheets of stone hang from the roof here in folds, like cloth hung up to dry, so thin that any light behind them shines through red and gold. Knock one and it rings. Behind them the passage goes on down toward the heave and the break.', 0, 0, 'cave', 0, -43, 7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-curtains', 'south', 'the-heave', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-curtains', 'north', 'the-flowstone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bears-stair', 'door', 'The Bear''s Stair', 'The back of the bear''s bed in the Ridge Cave goes on down here in a broken stair of rock, every step polished on its edge by something heavy going up and down it for a long time. Long grooves score the wall beside it as high as you can reach. Cold air comes up the stair from below and goes past you into the bear''s cave.', 0, 0, 'cave', 0, -49, 2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bears-stair', 'up', 'the-ridge-cave', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bears-stair', 'east', 'the-cold-breath', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bears-stair', 'south', 'the-scored-drop', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-breath', 'door', 'The Cold Breath', 'The air here comes out of a crack in the wall at the height of your face, a steady breath of it, colder than the rest of the cave, smelling of nothing at all. Hold your hand to the crack and it is like holding it to winter.', 0, 0, 'cave', 0, -48, 2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-breath', 'west', 'the-bears-stair', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-breath', 'east', 'the-whistling-hole', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-whistling-hole', 'door', 'The Whistling Hole', 'The draught goes through a hole in a thin wall of rock here and the hole sings: a long low note that rises when the air comes harder and sinks when it eases, and never stops. Animals do not lie up near it. The floor is clean.', 0, 0, 'cave', 0, -47, 2, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-whistling-hole', 'west', 'the-cold-breath', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-whistling-hole', 'south', 'the-bear-path', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bear-path', 'door', 'The Bear Path', 'A path worn smooth through the rubble of the floor, wide and deep, the path of something heavy that has gone along it the same way for years. Coarse brown hair is snagged on the rock at shoulder height. The path goes on south into the dark.', 0, 0, 'cave', 0, -47, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bear-path', 'north', 'the-whistling-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bear-path', 'south', 'the-dark-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-scored-drop', 'door', 'The Scored Drop', 'The floor drops a man''s height here, and the rock face you climb down is scored all over in long fours, gouged deep, old marks and new over them. Whatever made them climbs up and down here often, and does not need a handhold.', 0, 0, 'cave', 0, -49, 3, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scored-drop', 'north', 'the-bears-stair', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scored-drop', 'south', 'the-claw-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-claw-floor', 'door', 'The Claw Floor', 'A wide floor of packed earth, churned up and dug over, hollows scraped in it the size of a bed, the earth thrown up in heaps. Deer bones lie about it, bitten across. The smell of bear is everywhere here and not old.', 0, 0, 'cave', 0, -49, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-claw-floor', 'north', 'the-scored-drop', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-claw-floor', 'east', 'the-bears-wallow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-claw-floor', 'south', 'the-shaft-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bears-wallow', 'door', 'The Bear''s Wallow', 'A hollow in the floor where water seeps in and lies in a slick of mud, rolled in and churned, with long brown hair caught all round its edge. The mud holds the print of something enormous lying down in it. The print is still wet.', 0, 0, 'cave', 0, -48, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bears-wallow', 'west', 'the-claw-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bears-wallow', 'east', 'the-dark-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dark-turn', 'door', 'The Dark Turn', 'The passage turns here and goes down, and the dark seems thicker past the turn than before it, as if the cave had stopped bothering with you. The walls are close. The air comes up past you from below and is colder than it has been.', 0, 0, 'cave', 0, -47, 4, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-turn', 'north', 'the-bear-path', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-turn', 'west', 'the-bears-wallow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-turn', 'south', 'the-slick', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-slick', 'door', 'The Slick', 'The floor tilts here and is coated in a film of wet clay as slippery as ice, and you go down it on your back as often as your feet. At the bottom it levels. There are scrape marks in the clay of everything else that has come down it the same way.', 0, 0, 'cave', 0, -47, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slick', 'north', 'the-dark-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slick', 'east', 'the-narrows', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-narrows', 'door', 'The Narrows', 'The walls come in on both sides until you go through sideways, and stay that way for longer than you like. You cannot turn round here. You cannot see what is ahead of you or behind you, and the draught blows past your face toward the way you came.', 0, 0, 'cave', 0, -46, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-narrows', 'east', 'the-calcite-crawl', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-narrows', 'west', 'the-slick', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shaft-head', 'door', 'The Shaft Head', 'The floor opens in a shaft going down, wide as a well, its sides streaked with old water marks, and the cold comes up it like a breath held a long time and let go. There is a ledge round the top of it and a way down its side, steep and wet.', 0, 0, 'cave', 0, -49, 5, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-head', 'north', 'the-claw-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-head', 'south', 'the-ox-bow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-head', 'down', 'the-shaft-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ox-bow', 'door', 'The Ox-Bow', 'The passage loops round on itself in a long bend, the walls cut smooth and undercut on the outside of the curve where a river once ran hard round it. The river is gone. It left its marks at the height of your head.', 0, 0, 'cave', 0, -49, 6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ox-bow', 'north', 'the-shaft-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ox-bow', 'west', 'the-old-water-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ox-bow', 'south', 'the-tight-bend', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-old-water-line', 'door', 'The Old Water Line', 'A line runs along both walls at the height of your shoulder, stained and smooth, where water stood once for a long time. Below the line the rock is clean. Above it, it is crusted and rough. Down here the river was a long time drying.', 0, 0, 'cave', 0, -50, 6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-water-line', 'east', 'the-ox-bow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-water-line', 'west', 'the-dry-sink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dry-sink', 'door', 'The Dry Sink', 'A bowl in the floor where the old water drained away down a hole in its middle, the hole choked now with silt and pebbles. Put your ear to it and you can hear water below, far down, running fast.', 0, 0, 'cave', 0, -51, 6, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-sink', 'east', 'the-old-water-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-sink', 'south', 'the-sand-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sand-bank', 'door', 'The Sand Bank', 'A bank of sand dropped by the old river runs along one wall, soft and deep. Something has dug into it in a dozen places, short scrapes, and left the holes open. Something smaller has been in the holes since.', 0, 0, 'cave', 0, -51, 7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sand-bank', 'north', 'the-dry-sink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sand-bank', 'south', 'the-listening-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-listening-floor', 'door', 'The Listening Floor', 'The floor is thin rock here, and under it, loud and very near, water is running. You can feel it through your feet. In places the floor rings hollow, and in one place there is a crack you could put a hand into and feel the wet air coming up.', 0, 0, 'cave', 0, -51, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-listening-floor', 'north', 'the-sand-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-listening-floor', 'south', 'the-wet-step', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wet-step', 'door', 'The Wet Step', 'A step down in the floor, slick with wet, where the way from the fern hole meets the way from the river''s old bed. Water drips from the roof here and fern spores have come in on the air and grown in the drip, pale and small and nearly white.', 0, 0, 'cave', 0, -51, 9, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-step', 'north', 'the-listening-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-step', 'west', 'the-fern-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-step', 'south', 'the-sound-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-step', 'east', 'the-hauled-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-fern-hole', 'door', 'The Fern Hole', 'The bank of ferns above has fallen in here, and the hole is hung with fern and moss and roots, and what light the wood has comes down through them. The floor below it is soft and wet. The sound of water running is very loud, and comes from under your feet.', 0, 0, 'cave', 0, -52, 9, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fern-hole', 'east', 'the-wet-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fern-hole', 'up', 'the-ferny-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sound-hole', 'door', 'The Sound Hole', 'A hole in the floor going down, and out of it the roar of water, so loud here you cannot hear yourself. Spray comes up it. The rock round the hole is wet and green and the way down it is a climb down a wet wall, toward the noise.', 0, 0, 'cave', 0, -51, 10, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sound-hole', 'north', 'the-wet-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sound-hole', 'down', 'the-falls-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hauled-way', 'door', 'The Hauled Way', 'Something heavy has been hauled along the floor here from the fern hole, and the moss that grows in the wet near the hole is torn up in a long stripe going east. A hoof has been left in the stripe. Further on, the stripe is blood.', 0, 0, 'cave', 0, -50, 9, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hauled-way', 'west', 'the-wet-step', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hauled-way', 'east', 'the-kill-hole', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-kill-hole', 'door', 'The Kill Hole', 'A pocket off the passage where the hauled way ends, and in it what is left of what was hauled: a roe''s bones, and its skin turned inside out in a heap. The bones are scattered and some carried off. Shed tawny fur lies on the floor in tufts.', 0, 0, 'cave', 0, -49, 9, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-kill-hole', 'west', 'the-hauled-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-kill-hole', 'north', 'the-low-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-low-arch', 'door', 'The Low Arch', 'A low arch of rock you stoop under, the stone of it bright and smooth on the underside where something has rubbed past it going under, low and long, many times. Your shoulders touch it either side.', 0, 0, 'cave', 0, -49, 8, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-arch', 'south', 'the-kill-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-arch', 'north', 'the-tight-bend', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-tight-bend', 'door', 'The Tight Bend', 'The passage doubles back so sharply here you have to fold yourself round the corner. On the inside of the bend the rock is worn to a gloss at knee height. Around the corner the air moves again.', 0, 0, 'cave', 0, -49, 7, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tight-bend', 'north', 'the-ox-bow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tight-bend', 'south', 'the-low-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sump-mouth', 'door', 'The Sump Mouth', 'The river comes out from under the rock here. A wall of stone goes down into black water, and the water wells out from under it, cold and fast and silent, from somewhere nobody has been. There is no way on but downstream.', 0, 0, 'cave', 0, -50, -3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sump-mouth', 'south', 'the-black-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-black-water', 'door', 'The Black Water', 'The river runs black and fast between walls of wet rock with no bank to speak of, only a ledge along one side you go along with your back to the stone. Nothing glows here. The water is loud and the air over it is colder than the water.', 0, 0, 'cave', 0, -50, -2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-water', 'north', 'the-sump-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-water', 'west', 'the-under-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-water', 'south', 'the-glow-reach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-under-pool', 'door', 'The Under-Pool', 'The river spreads sideways here into a pool under a low roof, wide and still and black, so deep that a stone dropped in does not seem to reach anything. The edge of it is a shelf of smooth rock sloping down into the water. Something big moves under the surface, and the surface hardly moves.', 0, 0, 'cave', 0, -51, -2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-pool', 'east', 'the-black-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-glow-reach', 'door', 'The Glow Reach', 'The first lights. A few pale points of green hang in the dark over the river, low, each on a thread finer than hair, and as you watch, more of them are there. They are glow-worms, and the roof here is beginning to be full of them.', 0, 0, 'cave', 0, -50, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glow-reach', 'north', 'the-black-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glow-reach', 'south', 'the-starry-roof', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-starry-roof', 'door', 'The Starry Roof', 'The roof over the river is crowded with glow-worms, thousands of them, so that it looks like a night sky with too many stars, and their light lies green on the moving water. Their threads hang down in curtains. Anything that flies into them is held, and eaten.', 0, 0, 'cave', 0, -50, 0, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-starry-roof', 'north', 'the-glow-reach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-starry-roof', 'south', 'the-river-shingle', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-starry-roof', 'east', 'the-roost-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-river-shingle', 'door', 'The River Shingle', 'The river has left a bank of shingle here on the inside of a bend, round grey stones rattling under your feet, and the glow-worms above put a green shine on every wet one. The water runs past close, fast and smooth and deep.', 0, 0, 'cave', 0, -50, 1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-shingle', 'north', 'the-starry-roof', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-shingle', 'south', 'the-river-bend', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-river-bend', 'door', 'The River Bend', 'The river turns here hard against the far wall and has cut it back into a deep undercut, the rock hanging out over the water. Glow-worms hang under the undercut in a thick green fringe. On this side there are old marks of nails in the rock, where something was once fixed.', 0, 0, 'cave', 0, -50, 2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-bend', 'north', 'the-river-shingle', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-bend', 'south', 'the-diggers-bridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-diggers-bridge', 'door', 'The Diggers'' Bridge', 'A bridge of planks crosses the river here on two baulks of timber wedged between the rocks, the boards grey and soft with wet, one of them gone. It was built by people, carefully. The glow-worms have hung their threads from the underside of it.', 0, 0, 'cave', 0, -50, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-diggers-bridge', 'north', 'the-river-bend', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-diggers-bridge', 'east', 'the-bridge-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-diggers-bridge', 'south', 'the-foxfire-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-foxfire-wall', 'door', 'The Foxfire Wall', 'Rotten timber is jammed into the cracks of the wall here, the wreck of old props carried down by the water, and the rot on it glows: a cold blue-green light that comes from the wood itself, enough to see your hand by. The river runs past it lit from the side.', 0, 0, 'cave', 0, -50, 4, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-foxfire-wall', 'north', 'the-diggers-bridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-foxfire-wall', 'south', 'the-deep-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-deep-run', 'door', 'The Deep Run', 'The river runs deep and narrow here, a fast smooth channel with the bank a ledge above it, and the glow-worms on the roof are mirrored in it, broken and mended and broken again. There is no shallow here. Whatever is in the water is in deep water.', 0, 0, 'cave', 0, -50, 5, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-run', 'north', 'the-foxfire-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-run', 'south', 'the-ford', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ford', 'door', 'The Ford', 'The river spreads over a bed of stones and runs shallow, a few hands deep, quick and cold enough to ache. Stepping stones have been set across it. Glow-worms crowd the roof over the ford and the stones shine green under the water.', 0, 0, 'cave', 0, -50, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford', 'north', 'the-deep-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford', 'east', 'the-wet-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford', 'south', 'the-long-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-long-pool', 'door', 'The Long Pool', 'The river slows here into a long pool with the roof close over it and the glow-worms so thick and so near you could touch them. The water is clear and very deep in the middle, and pale shapes hang still in it, fish with no eyes, and something larger, further down, paler.', 0, 0, 'cave', 0, -50, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-pool', 'north', 'the-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-pool', 'west', 'the-deep-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-pool', 'south', 'the-river-shelf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-deep-pool', 'door', 'The Deep Pool', 'A side pool off the long pool, under rock, with no light at all. The edge goes down steep and smooth and the water is very cold. Bones lie on the shelf at the water''s edge, picked white, and some of them are a man''s.', 0, 0, 'cave', 0, -51, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-pool', 'east', 'the-long-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-river-shelf', 'door', 'The River Shelf', 'A shelf of rock runs along above the water here, wide enough to walk, polished by feet. The river below is lit green by the glow-worms over it and you can see the bottom in places, and in places you cannot.', 0, 0, 'cave', 0, -50, 8, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-shelf', 'north', 'the-long-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-shelf', 'south', 'the-narrowing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-narrowing', 'door', 'The Narrowing', 'The walls close in and the river runs faster between them, piling up against the rock and roaring. The glow-worms grow thinner here, their threads blown sideways by the air that comes with the fast water. Ahead the roar is louder.', 0, 0, 'cave', 0, -50, 9, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-narrowing', 'north', 'the-river-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-narrowing', 'south', 'the-rapids', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rapids', 'door', 'The Rapids', 'The river breaks white over a staircase of rocks and the noise of it fills everything. Spray hangs in the air and puts out the glow-worms'' light, and puts out any flame held near it. You go along the wall by feel, wet through.', 0, 0, 'cave', 0, -50, 10, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rapids', 'north', 'the-narrowing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rapids', 'south', 'the-falls-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-falls-foot', 'door', 'The Falls Foot', 'The river goes over a lip of rock in a fall twice your height and hits the pool below with a sound you feel in your chest. Spray comes up off it in a cold cloud and goes up a hole in the roof, and the roar goes up with it. Nothing can be heard over it.', 0, 0, 'cave', 0, -50, 11, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-falls-foot', 'north', 'the-rapids', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-falls-foot', 'up', 'the-sound-hole', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-falls-foot', 'south', 'the-falls-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-falls-pool', 'door', 'The Falls Pool', 'The pool under the falls is round and deep and churning, foam going round on it. Away from the falls the roof is low and the glow-worms come back, few and faint, and the water calms. A long scum of foam drifts off downstream.', 0, 0, 'cave', 0, -50, 12, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-falls-pool', 'north', 'the-falls-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-falls-pool', 'south', 'the-river-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-river-turn', 'door', 'The River Turn', 'The river turns east here, under a low wide roof, and slows, and spreads. Silt lies on the inside of the turn and something has walked through it on four short legs, dragging a tail. There is no light here.', 0, 0, 'cave', 0, -50, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-turn', 'north', 'the-falls-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-river-turn', 'east', 'the-low-roof', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-low-roof', 'door', 'The Low Roof', 'The roof comes down until it is a hand''s breadth over the water, and the way along the bank is a crawl on your belly in the wet with the rock pressing down. In high water this would be under the river. The rock overhead is clean of mud and silt to a line well above your head.', 0, 0, 'cave', 0, -49, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-roof', 'west', 'the-river-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-roof', 'east', 'the-silt-banks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-silt-banks', 'door', 'The Silt Banks', 'The roof lifts again over wide banks of soft grey silt, the river slow and quiet between them. You sink to the ankle at every step. A side way leads off into pools beside the river, and the silt is printed with small tracks going to and from them.', 0, 0, 'cave', 0, -48, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silt-banks', 'west', 'the-low-roof', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silt-banks', 'east', 'the-glow-tunnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silt-banks', 'north', 'the-salamander-pools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-glow-tunnel', 'door', 'The Glow Tunnel', 'A round tunnel of rock with the river filling its floor and the glow-worms filling its roof, so you go through a tube of green light along a ledge with the water beside you. It is very beautiful and very quiet and there is nothing to hold onto.', 0, 0, 'cave', 0, -47, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glow-tunnel', 'west', 'the-silt-banks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glow-tunnel', 'east', 'the-wide-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wide-water', 'door', 'The Wide Water', 'The tunnel opens into a wide chamber nearly all water, the river spreading into a lake with the glow-worms'' light on it. The bank goes round the edge. Out in the middle the surface sometimes swells, slowly, as if something were turning over far down.', 0, 0, 'cave', 0, -46, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wide-water', 'west', 'the-glow-tunnel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wide-water', 'east', 'the-still-reach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-still-reach', 'door', 'The Still Reach', 'The river runs so slow here it seems not to run at all, flat and black with a scatter of green light on it from the roof. The bank is wide and dry. A side passage leads off away from the water, and the cold air comes out of it, not off the river.', 0, 0, 'cave', 0, -45, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-still-reach', 'west', 'the-wide-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-still-reach', 'east', 'the-rising-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-still-reach', 'north', 'the-old-sink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rising-water', 'door', 'The Rising Water', 'The river is climbing here: the bed tilts up and the water comes up it against the slope, slow and heavy, pushed from behind. The roof comes down to meet it. The glow-worms hang low over the water, their light green on the slope.', 0, 0, 'cave', 0, -44, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rising-water', 'west', 'the-still-reach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rising-water', 'east', 'the-under-spring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-under-spring', 'door', 'The Under-Spring', 'The water fills the passage nearly to the roof and pushes upward through a round shaft in it, welling up, and you wade chest-deep with a hand on the rock and the glow-worms an arm''s length from your face.', 0, 0, 'cave', 0, -43, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-spring', 'west', 'the-rising-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-spring', 'east', 'the-spring-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-spring-foot', 'door', 'The Spring Foot', 'The foot of the Spring''s Throat: the whole river goes up here through a round shaft in the roof, welling up cold and heavy, and spills out above into the mire. You can climb up beside it, through it, holding your breath. Up there is the wood.', 0, 0, 'cave', 0, -42, 13, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-foot', 'west', 'the-under-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-foot', 'up', 'the-spring-throat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-foot', 'north', 'the-cold-sand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-roost-water', 'door', 'The Roost Water', 'A side way leaves the river here and climbs, and the water that runs down it out of the roost is brown and stinks. The glow-worms stop where it starts. From up the slope comes a sound like rain that is not rain, the rustle of a great many small bodies.', 0, 0, 'cave', 0, -49, 0, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-water', 'west', 'the-starry-roof', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-water', 'north', 'the-guano-slope', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-guano-slope', 'door', 'The Guano Slope', 'A slope of droppings ankle-deep, soft and warm and stinking of ammonia so strong your eyes run. Beetles cover it, moving. The roof above is close and black and it is moving too.', 0, 0, 'cave', 0, -49, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-slope', 'south', 'the-roost-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-slope', 'east', 'the-north-roost', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-north-roost', 'door', 'The North Roost', 'The roof of this chamber is covered in bats, packed wing to wing, thousands of them, hanging and shifting and squeaking, and the floor is deep in what they drop. A light held up sets them stirring all over the roof, a ripple running away into the dark.', 0, 0, 'cave', 0, -48, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-roost', 'west', 'the-guano-slope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-roost', 'north', 'the-silk-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-roost', 'east', 'the-bat-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-silk-hall', 'door', 'The Silk Hall', 'Silk hangs from the roof of this chamber in sheets, grey and thick as sacking, from wall to wall, and the dead bats caught in it hang like leaves. The silk is strong. It catches on your face and hands and comes away with you. Something has been making it for a long time, and it is big.', 0, 0, 'cave', 0, -48, -2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silk-hall', 'south', 'the-north-roost', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-silk-hall', 'west', 'the-wrapped-things', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wrapped-things', 'door', 'The Wrapped Things', 'Bundles hang from the roof in the far corner of the silk, wrapped round and round, some the size of a bat, some the size of a dog, one the size of a man. The big one has a boot showing at the bottom of the wrapping.', 0, 0, 'cave', 0, -49, -2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wrapped-things', 'east', 'the-silk-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bat-way', 'door', 'The Bat Way', 'A high narrow passage the bats use, the walls rubbed dark by wings. Every dusk the whole roost goes out this way and up, and the air in it still smells of them. It is empty now. The floor is soft with droppings and bones of moths.', 0, 0, 'cave', 0, -47, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bat-way', 'west', 'the-north-roost', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bat-way', 'east', 'the-smoked-passage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-smoked-passage', 'door', 'The Smoked Passage', 'The roof here is black with soot, thick and old, and there are the ashes of fires on the floor in a row across the passage, built close together, as if somebody had wanted to fill the way with smoke. Dead bats lie in the ash, dried out, a great many of them.', 0, 0, 'cave', 0, -46, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-smoked-passage', 'west', 'the-bat-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-smoked-passage', 'east', 'the-deep-camp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ladder-foot', 'door', 'The Ladder Foot', 'The roots of the Root Chimney end here, and below where they end, ladders have been lashed to the rock, three of them, one under the other, the rungs worn pale by hands. They were brought down from above. At the foot of them the floor has been swept.', 0, 0, 'cave', 0, -35, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ladder-foot', 'up', 'the-root-chimney', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ladder-foot', 'west', 'the-pick-work', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pick-work', 'door', 'The Pick Work', 'The passage was too narrow for a man with a load, and somebody made it wider: the walls are cut back on both sides with picks, the marks short and even and all the same height, a good day''s work done by people who knew how. The spoil has been carried off.', 0, 0, 'cave', 0, -36, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pick-work', 'east', 'the-ladder-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pick-work', 'west', 'the-first-camp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-first-camp', 'door', 'The First Camp', 'A camp in a dry chamber: a ring of stones round a hearth, a stack of firewood under a cloth, a row of empty sacks hung on pegs driven into the rock. The hearth is not cold. Lamp soot blackens the roof over a niche in the wall where a lamp has stood night after night.', 0, 0, 'cave', 0, -37, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-camp', 'east', 'the-pick-work', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-camp', 'north', 'the-lamp-store', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-camp', 'west', 'the-tally-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-camp', 'south', 'the-dry-stretch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-lamp-store', 'door', 'The Lamp Store', 'A niche cut back into the rock, shelved with planks, and on the shelves: jars of oil sealed with wax, bundles of wick, spare glass wrapped in rag, a pot of tallow, a flint. All in rows. Somebody keeps this in order still. The shelf at the front is empty in the shape of a lamp.', 0, 0, 'cave', 0, -37, 2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lamp-store', 'south', 'the-first-camp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-tally-wall', 'door', 'The Tally Wall', 'The wall here is covered in tallies cut with a point, groups of four strokes and one across, row under row, and a mark at the head of each row that might be a name. The rows stop at different lengths. One row goes on long after the rest have stopped, and the last strokes are cut deep.', 0, 0, 'cave', 0, -38, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tally-wall', 'east', 'the-first-camp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tally-wall', 'west', 'the-barrow-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-barrow-run', 'door', 'The Barrow Run', 'Planks have been laid end to end along the floor here as a run for barrows, and the rut of a single wheel is worn into them. A barrow stands on the run, tipped forward, loaded with cut stone, its handles still up as if the man pushing it had only now let go.', 0, 0, 'cave', 0, -39, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-barrow-run', 'east', 'the-tally-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-barrow-run', 'north', 'the-propped-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-barrow-run', 'west', 'the-widened-squeeze', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-propped-way', 'door', 'The Propped Way', 'Timber props hold up the roof here, posts and a cap-beam every few paces, squared and pegged by somebody who knew timber. The roof was bad. You can see where it came down before the props went in, and the props are holding it now, grey and wet and bowed.', 0, 0, 'cave', 0, -39, 2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-propped-way', 'south', 'the-barrow-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-propped-way', 'north', 'the-sagging-props', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sagging-props', 'door', 'The Sagging Props', 'The props here have begun to go: the caps bowed, the posts leaning, one split from top to bottom and still standing because the rock has not yet finished deciding. Little falls of grit come down when you pass. Nobody has put in new props for a long time.', 0, 0, 'cave', 0, -39, 1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sagging-props', 'south', 'the-propped-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sagging-props', 'west', 'the-stone-store', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-stone-store', 'door', 'The Stone Store', 'Cut stone is stacked here against the wall in neat courses, blocks squared for building, enough for a wall the height of a man. It was carried down from above, on backs and in barrows. None of it has been used. The top of the stack has a coat of dust on it as thick as cloth.', 0, 0, 'cave', 0, -40, 1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-store', 'east', 'the-sagging-props', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stone-store', 'west', 'the-water-butts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-widened-squeeze', 'door', 'The Widened Squeeze', 'A squeeze somebody opened up with picks and wedges, the cut faces fresh against the old water-worn rock, and the wedges still in the last crack, driven halfway home. The hammer lies on the floor beside them where it was put down.', 0, 0, 'cave', 0, -40, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-widened-squeeze', 'east', 'the-barrow-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-widened-squeeze', 'west', 'the-cold-camp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-camp', 'door', 'The Cold Camp', 'A second camp: hearth, woodpile, sacks, a pot on a hook over the hearth with something dried black in the bottom of it. The ash in the hearth is old and grey and has a skin on it. Nobody has sat at this fire for a long time. The cold air comes through the camp from the west and goes on up.', 0, 0, 'cave', 0, -41, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-camp', 'east', 'the-widened-squeeze', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-camp', 'north', 'the-sleeping-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-camp', 'south', 'the-broken-ladder', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sleeping-shelf', 'door', 'The Sleeping Shelf', 'A long shelf of rock along the wall has been made into a bed for many: bracken laid on it, and blankets on the bracken, eight or nine places side by side, each with a hollow worn in it. The blankets are pulled back in every place, as they would be in a house woken in the night.', 0, 0, 'cave', 0, -41, 2, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sleeping-shelf', 'south', 'the-cold-camp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sleeping-shelf', 'north', 'the-water-butts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-water-butts', 'door', 'The Water Butts', 'Two big butts of water stand here on a ledge, staved and hooped, with a dipper hung on the side of one. The water in them is clear and cold. A line has been cut in the rock above each to show where the water should be kept up to, and both are well below it.', 0, 0, 'cave', 0, -41, 1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-butts', 'east', 'the-stone-store', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-butts', 'south', 'the-sleeping-shelf', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-water-butts', 'west', 'the-carry-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-carry-way', 'door', 'The Carry Way', 'A narrow way where everything had to go through on men''s backs: the walls are rubbed smooth at shoulder height on both sides, and the floor is littered with chips of the stone they carried. A broken carrying frame leans against the wall, its straps rotted.', 0, 0, 'cave', 0, -42, 1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-carry-way', 'east', 'the-water-butts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-carry-way', 'north', 'the-mortar-trough', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-mortar-trough', 'door', 'The Mortar Trough', 'A wooden trough of mortar stands here gone hard as the rock round it, with the trowel set in it at an angle and the hoe beside it, both held fast. Sacks of lime are stacked by the trough, split, the lime spilled and gone to stone on the floor.', 0, 0, 'cave', 0, -42, 0, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mortar-trough', 'south', 'the-carry-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mortar-trough', 'north', 'the-pick-marks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pick-marks', 'door', 'The Pick Marks', 'The diggers were cutting a new way here. The face at the end of the passage is half-cut, the pick marks fresh and pale, and a pick is still in the rock, buried to the eye in the last stroke, the handle sticking out level. Cold air comes out of the crack the stroke opened.', 0, 0, 'cave', 0, -42, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pick-marks', 'south', 'the-mortar-trough', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pick-marks', 'west', 'the-first-stopping', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-first-stopping', 'door', 'The First Stopping', 'A wall of cut stone and mortar has been built across the passage here, a good wall, waist-high on one side and rising to chest-high on the other, the courses true. It is not finished. You climb over the low end. The cold air comes over the top of it as it came before the wall was there.', 0, 0, 'cave', 0, -43, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-stopping', 'east', 'the-pick-marks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-stopping', 'west', 'the-carried-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-carried-stone', 'door', 'The Carried Stone', 'Stone lies about the floor here where it was set down, singly and in twos, block after block, not stacked, not laid, each where the man carrying it stopped. A line of them goes off ahead along the passage, further apart the further it goes, like a trail.', 0, 0, 'cave', 0, -44, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-carried-stone', 'east', 'the-first-stopping', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-carried-stone', 'west', 'the-deep-camp', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-deep-camp', 'door', 'The Deep Camp', 'The last camp and the deepest. A good fire burns here, low, in a hearth of cut stone, and bedding is laid round it, and food hangs from a peg out of reach of anything that digs. A box stands against the wall, iron-bound, with a lock as big as a fist. The people who keep this camp are not far away.', 0, 0, 'cave', 0, -45, -1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-camp', 'west', 'the-smoked-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-camp', 'east', 'the-carried-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-camp', 'south', 'the-stopping', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-stopping', 'door', 'The Stopping', 'The great wall. It was meant to close the passage from floor to roof and it closes two-thirds of it, every course of it laid true and pointed, a proper wall in the middle of a cave. Over the top there is a gap the width of a door, and the cold comes through it like water over a weir. The ladder up to the gap is still standing.', 0, 0, 'cave', 0, -45, 0, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stopping', 'north', 'the-deep-camp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stopping', 'south', 'the-diggers-stair', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-diggers-stair', 'door', 'The Diggers'' Stair', 'Behind the stopping the way goes down, and the diggers cut steps into it, rough and steep, a rope pegged along the wall to hold. The rock changes as you go down. It gets colder with every step, and the air comes up the stair steady and hard, out of the dark below.', 0, 0, 'cave', 0, -45, 1, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-diggers-stair', 'north', 'the-stopping', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-diggers-stair', 'down', 'the-stair-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bridge-end', 'door', 'The Bridge End', 'The far end of the plank bridge, where a path goes up off the river into the rock. A post is set in the ground at the bridge foot and a lantern hook is nailed to it, empty. The path has been trodden by many boots, going both ways.', 0, 0, 'cave', 0, -49, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-end', 'west', 'the-diggers-bridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-end', 'east', 'the-foxfire-cut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-foxfire-cut', 'door', 'The Foxfire Cut', 'A passage cut through soft rock, and the old props in it have rotted where they stand and glow: every post a pillar of cold blue-green light, the caps glowing overhead, so you walk through a row of them like a row of lamps. They will not bear any weight now.', 0, 0, 'cave', 0, -48, 3, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-foxfire-cut', 'west', 'the-bridge-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-foxfire-cut', 'south', 'the-weeping-wall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-weeping-wall', 'door', 'The Weeping Wall', 'Water seeps out of the whole face of the wall here and runs down it in a thin sheet, and the rot that grows in the wet glows, a faint blue light in patches and streaks all over the stone. The floor is a shallow stream.', 0, 0, 'cave', 0, -48, 4, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weeping-wall', 'north', 'the-foxfire-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weeping-wall', 'south', 'the-seep-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-seep-hall', 'door', 'The Seep Hall', 'A low wide hall where water drips everywhere and stands in pools on the floor, and the walls are crusted with a glowing rot that lights the whole hall dimly blue. The drips make rings in the pools. The cold air comes down from the shaft at the far end.', 0, 0, 'cave', 0, -48, 5, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-seep-hall', 'north', 'the-weeping-wall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-seep-hall', 'south', 'the-shaft-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shaft-foot', 'door', 'The Shaft Foot', 'The foot of the Shaft Head''s shaft: water marks run down its walls from far above, and the cold air goes up it like a chimney drawing. There is foxfire in the wet at the bottom, a faint blue. The way up is the climb you came down.', 0, 0, 'cave', 0, -48, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-foot', 'north', 'the-seep-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-foot', 'up', 'the-shaft-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-foot', 'west', 'the-wet-ledge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shaft-foot', 'east', 'the-glow-crawl', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wet-ledge', 'door', 'The Wet Ledge', 'A ledge of wet rock runs from the shaft''s foot down to the ford, slick with green, the foxfire on the wall beside it bright enough to see the edge by. The river is loud below. A rope has been pegged along the wall here, and the pegs are rusted thin.', 0, 0, 'cave', 0, -49, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-ledge', 'west', 'the-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-ledge', 'east', 'the-shaft-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-glow-crawl', 'door', 'The Glow Crawl', 'A crawl through wet rock, the roof low over your back and glowing with rot, so you go through it with blue light an inch from your eyes. The floor is mud. Things have crawled through here before you, and the mud keeps their marks, small and many.', 0, 0, 'cave', 0, -47, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glow-crawl', 'west', 'the-shaft-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glow-crawl', 'east', 'the-pale-pools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pale-pools', 'door', 'The Pale Pools', 'A chamber of shallow pools, each clear and cold, lit faintly blue from the foxfire on the walls. Pale salamanders lie in the pools, white and still, their skin so thin you can see the dark of their insides. They do not move when you come close.', 0, 0, 'cave', 0, -46, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-pools', 'west', 'the-glow-crawl', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-pools', 'east', 'the-dark-stretch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dark-stretch', 'door', 'The Dark Stretch', 'The rock is dry here and nothing glows. It is black, the black of having no eyes, and the only sound is your own breathing and the far-off sound of water behind you. The floor is dust.', 0, 0, 'cave', 0, -45, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-stretch', 'west', 'the-pale-pools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-stretch', 'east', 'the-dry-gallery', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dry-gallery', 'door', 'The Dry Gallery', 'A long gallery of dry rock, dark, its floor fine dust. The dust has been walked. Booted feet went this way, a line of them, going west, and over the bootprints are the prints of something with long claws and no pad.', 0, 0, 'cave', 0, -44, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-gallery', 'west', 'the-dark-stretch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-gallery', 'east', 'the-crushed-props', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-crushed-props', 'door', 'The Crushed Props', 'The roof came down here onto the props and took them with it: timbers splintered and thrown down in a heap with the rock, a way cleared through the fall at one side just wide enough. Under the heap a hand shows, a man''s, grey with the dust.', 0, 0, 'cave', 0, -43, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crushed-props', 'west', 'the-dry-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crushed-props', 'east', 'the-cut-through', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cut-through', 'door', 'The Cut-Through', 'A short passage cut through the rock with picks to join two caves that did not meet, straight and square, the floor level. It is a piece of work that does not belong in a cave, and the cave has not yet done anything about it.', 0, 0, 'cave', 0, -42, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-through', 'west', 'the-crushed-props', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-through', 'east', 'the-crossed-ways', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-broken-ladder', 'door', 'The Broken Ladder', 'A ladder goes down a step in the floor here, and its third rung is broken and the ones below it hang by one side. The rock below has the scrape marks of the men who fell. Beside it someone has cut footholds into the rock instead.', 0, 0, 'cave', 0, -41, 4, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ladder', 'north', 'the-cold-camp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-ladder', 'south', 'the-wet-cut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wet-cut', 'door', 'The Wet Cut', 'A cut passage where the water has come back in: a stream runs along the floor where the diggers'' boots went, and the walls they cut so square are going green. The wet has not yet started to glow.', 0, 0, 'cave', 0, -41, 5, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-cut', 'north', 'the-broken-ladder', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-cut', 'south', 'the-crossed-ways', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-crossed-ways', 'door', 'The Crossed Ways', 'Two passages cross here, one natural and one cut. On the wall where they meet someone has cut an arrow with a pick, pointing down the cut way, and beside it a mark like a door.', 0, 0, 'cave', 0, -41, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crossed-ways', 'west', 'the-cut-through', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crossed-ways', 'north', 'the-wet-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crossed-ways', 'south', 'the-foxfire-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-foxfire-hall', 'door', 'The Foxfire Hall', 'A high hall of wet rock lit blue from end to end by the rot that grows on it, the light coming off the walls in sheets so you can see the whole shape of the hall at once. In the middle of it there is a shaft going up, the Cold Well''s, and the air goes up it.', 0, 0, 'cave', 0, -41, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-foxfire-hall', 'north', 'the-crossed-ways', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-foxfire-hall', 'east', 'the-well-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-well-foot', 'door', 'The Well Foot', 'The foot of the Cold Well. The air comes past you and goes up the well hard, out of the lower ways, and the handholds go up in the rock above you into the black. Somebody has drawn a mark on the wall here in soot, a ring, and put a line through it.', 0, 0, 'cave', 0, -40, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-foot', 'west', 'the-foxfire-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-foot', 'up', 'the-cold-well', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-foot', 'east', 'the-blue-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-foot', 'south', 'the-well-passage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dry-stretch', 'door', 'The Dry Stretch', 'A dry way leading down from the first camp, dark, dusty, worn by boots. There are lamp-hooks driven into the wall at every twentieth pace, and no lamps on them.', 0, 0, 'cave', 0, -37, 4, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-stretch', 'north', 'the-first-camp', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-stretch', 'south', 'the-dead-glow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dead-glow', 'door', 'The Dead Glow', 'The walls are crusted with rot here as they are where it glows, but here it does not glow: it is dry and dead and black. Somebody has scraped at it with a blade, as if to see whether it would light again.', 0, 0, 'cave', 0, -37, 5, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-glow', 'north', 'the-dry-stretch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-glow', 'south', 'the-hanging-silk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hanging-silk', 'door', 'The Hanging Silk', 'Threads of silk hang across the passage, singly, at the height of your face and your knees, too fine to see. You walk into them. Every one of them goes back along the wall into the dark ahead, toward a sound like rain.', 0, 0, 'cave', 0, -37, 6, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-silk', 'north', 'the-dead-glow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hanging-silk', 'south', 'the-east-roost', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-blue-passage', 'door', 'The Blue Passage', 'A wet passage between the well and the roost, its walls glowing blue in patches where the water runs, so the light comes and goes along it. The air smells more and more of ammonia going east.', 0, 0, 'cave', 0, -39, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-passage', 'west', 'the-well-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-blue-passage', 'east', 'the-roost-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-roost-edge', 'door', 'The Roost Edge', 'The foxfire stops and the dark starts, and the floor goes soft with droppings. Ahead there is the sound of many wings shifting at once, a great dry rustle, and a smell that closes your throat.', 0, 0, 'cave', 0, -38, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-edge', 'west', 'the-blue-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-edge', 'east', 'the-east-roost', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-east-roost', 'door', 'The East Roost', 'A high chamber with a roof alive with bats, packed and shifting, the floor a slope of droppings with beetles moving over it. Silk hangs among the bats in long grey ropes, and some of the bats in it are not moving.', 0, 0, 'cave', 0, -37, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-roost', 'north', 'the-hanging-silk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-roost', 'west', 'the-roost-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-roost', 'east', 'the-spiders-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-roost', 'south', 'the-roost-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-spiders-gallery', 'door', 'The Spider''s Gallery', 'A gallery off the roost, hung with silk from end to end in sheets so thick that the far end is a grey wall. The floor is covered with the dry husks of bats. In the silk there are holes, round, bigger than your head, that something goes in and out of.', 0, 0, 'cave', 0, -36, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spiders-gallery', 'west', 'the-east-roost', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spiders-gallery', 'east', 'the-egg-sacs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-egg-sacs', 'door', 'The Egg Sacs', 'At the end of the gallery, fixed to the roof in a row, hang sacs of silk the size of loaves, tight and round and pale. One of them is split, and empty. The silk round them is thicker than anywhere, and fresh.', 0, 0, 'cave', 0, -35, 7, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-egg-sacs', 'west', 'the-spiders-gallery', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-roost-floor', 'door', 'The Roost Floor', 'The floor of the roost under the Bat Chimney, deep in droppings, warm. The chimney goes up from here into the upper cave, its sides black and slick, and the bats go up it. At dusk the noise of them going would deafen you.', 0, 0, 'cave', 0, -37, 8, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-floor', 'north', 'the-east-roost', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-floor', 'up', 'the-bat-chimney', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-roost-floor', 'south', 'the-guano-banks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-guano-banks', 'door', 'The Guano Banks', 'Banks of old droppings, years deep, grown over with a pale mould, the bottom of the roost where everything ends. Things have died here and been eaten by the beetles until only the shapes of them are left in the mould.', 0, 0, 'cave', 0, -37, 9, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-guano-banks', 'north', 'the-roost-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-well-passage', 'door', 'The Well Passage', 'A dry passage going south from the foot of the Cold Well, dark, the walls close. A boot lies on its side in the dust, an old one, with the sole worn through.', 0, 0, 'cave', 0, -40, 8, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-passage', 'north', 'the-well-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-passage', 'south', 'the-black-crawl', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-black-crawl', 'door', 'The Black Crawl', 'A crawl through dry dark rock, no light, no sound, the roof on your back. It goes on longer than seems right. Then the air ahead gets wetter.', 0, 0, 'cave', 0, -40, 9, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-crawl', 'north', 'the-well-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-crawl', 'south', 'the-dry-pools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dry-pools', 'door', 'The Dry Pools', 'A chamber of pools that have dried, their beds cracked into plates, their rims high and white. The salamanders that lived in them are in them still, dried flat. Water can be heard somewhere ahead, more than one way.', 0, 0, 'cave', 0, -40, 10, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-pools', 'north', 'the-black-crawl', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dry-pools', 'west', 'the-glass-pool', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-glass-pool', 'door', 'The Glass Pool', 'One pool here still holds water, so clear and still that you see the bottom of it before you see the water, and put a foot in it without meaning to. It is very cold. Something pale moves at the bottom and is gone.', 0, 0, 'cave', 0, -41, 10, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glass-pool', 'east', 'the-dry-pools', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-glass-pool', 'west', 'the-lit-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-lit-steps', 'door', 'The Lit Steps', 'The floor goes down in steps of wet rock, each lit faintly blue along its edge by the rot that grows in the wet, so the way down shows as a stair of lines in the dark. The sound of the river comes up from below.', 0, 0, 'cave', 0, -42, 10, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lit-steps', 'east', 'the-glass-pool', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lit-steps', 'south', 'the-spring-gallery', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-spring-gallery', 'door', 'The Spring Gallery', 'A gallery running down toward the river, the walls glowing blue in streaks where the water seeps, and the river''s sound filling it. Silt lies on the floor in ridges, left by water higher than this. The river comes up here sometimes.', 0, 0, 'cave', 0, -42, 11, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-gallery', 'north', 'the-lit-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spring-gallery', 'south', 'the-cold-sand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-sand', 'door', 'The Cold Sand', 'A slope of wet sand down to the foot of the spring, cold to the touch, ribbed by water. The river is very near and very loud, coming up through the rock just ahead, and the sand is printed all over with the marks of small feet going down to it.', 0, 0, 'cave', 0, -42, 12, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-sand', 'north', 'the-spring-gallery', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-sand', 'south', 'the-spring-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-salamander-pools', 'door', 'The Salamander Pools', 'Pools in the silt beside the river, lit faint green by a few glow-worms in the roof, and full of pale salamanders: dozens of them, lying still in the shallows with their pink gills spread. A track of bigger footprints comes down to the pools and goes back.', 0, 0, 'cave', 0, -48, 12, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salamander-pools', 'south', 'the-silt-banks', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-old-sink', 'door', 'The Old Sink', 'The side way off the still reach ends at a hole in the floor where the river once went down, before it found its way east. The hole is dry now and goes down a long way, and the cold air comes up it. Somebody has tied a rope off round a knob of rock at its lip.', 0, 0, 'cave', 0, -45, 12, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-sink', 'south', 'the-still-reach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-sink', 'down', 'the-sink-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-stair-foot', 'door', 'The Stair Foot', 'The diggers'' stair comes down onto a floor of flat stone, dressed and laid tight, so level that the cut steps end on it in a ragged edge like a torn cloth. Cold air comes up through the joints between the stones all over the floor, steadily, and the stone itself gives a faint grey light, enough to see the walls by. The walls are dressed stone too.', 0, 0, 'cave', 0, -44, 2, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stair-foot', 'up', 'the-diggers-stair', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stair-foot', 'west', 'the-spoil-heaps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stair-foot', 'south', 'the-first-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-spoil-heaps', 'door', 'The Spoil Heaps', 'The diggers tipped their spoil here, broken rock and earth in heaps that cover the floor and bank against the walls, and where it lies the stone''s light is put out. It is dark. A shovel stands in the nearest heap. The cold comes up out of the heaps anyway, through the spoil.', 0, 0, 'cave', 0, -45, 2, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spoil-heaps', 'east', 'the-stair-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-spoil-heaps', 'west', 'the-last-heading', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-last-heading', 'door', 'The Last Heading', 'The furthest the diggers got. A rough tunnel goes into the spoil and stops at a face of dressed stone they had begun to cut into, and given up on: a few pick-marks on it, shallow, and a pick with its point snapped off lying at the foot of it. Somebody has cut a row of tallies into the soft rock beside the face, and crossed them all out.', 0, 0, 'cave', 0, -46, 2, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-heading', 'east', 'the-spoil-heaps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-first-flags', 'door', 'The First Flags', 'Out of the diggers'' mess the floor runs on clean: great flat stones, each the size of a door, fitted so close you could not get a knife between them, and the cold air coming up through the joints regardless. The faint light comes off them evenly from no point you can find. Your steps are very loud.', 0, 0, 'cave', 0, -44, 3, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-flags', 'north', 'the-stair-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-flags', 'south', 'the-straight-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-straight-way', 'door', 'The Straight Way', 'A way of dressed stone running straight ahead, walls and floor and roof, as straight as a ruled line, further than the faint light lets you see. Nothing in a cave runs like this. Somebody built it, and built it to last, and it has.', 0, 0, 'cave', 0, -44, 4, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-straight-way', 'north', 'the-first-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-straight-way', 'west', 'the-west-door', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-straight-way', 'south', 'the-cold-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-road', 'door', 'The Cold Road', 'The straight way goes on, and the cold gets worse, the air coming up through the joints of the floor so steadily that it blows the dust along the stone in long lines, all toward the north. The faint light of the stone shows the dust moving.', 0, 0, 'cave', 0, -44, 5, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-road', 'north', 'the-straight-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-road', 'south', 'the-cross-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cross-hall', 'door', 'The Cross Hall', 'Two ways of dressed stone cross here in a square hall with a high flat roof, the corners of it square and true. The stone gives its faint grey light from every face, floor and walls and roof alike, so there are no shadows at all, not even yours.', 0, 0, 'cave', 0, -44, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cross-hall', 'north', 'the-cold-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cross-hall', 'west', 'the-west-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cross-hall', 'east', 'the-east-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cross-hall', 'south', 'the-long-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-long-flags', 'door', 'The Long Flags', 'The floor here is laid in long flags running the length of the way, and down the middle of them a track has been worn into the stone, shallow and smooth, by something that went this way more times than anyone could count. The track goes west at the hall behind you.', 0, 0, 'cave', 0, -44, 7, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-flags', 'north', 'the-cross-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-flags', 'south', 'the-sunk-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sunk-flags', 'door', 'The Sunk Flags', 'The floor has sunk here in the middle, the flags tilted down toward a long joint that has opened wider than the rest, a finger''s width, and the cold air comes up out of it hard enough to sing. The faint light is brighter along its edges, or seems to be.', 0, 0, 'cave', 0, -44, 8, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-flags', 'north', 'the-long-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-flags', 'south', 'the-rock-fall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rock-fall', 'door', 'The Rock Fall', 'The rock above the dressed roof has come down through it here and filled the way to half its height with broken stone, and under the fall the light of the stone is gone. It is dark. You climb over the heap with the roof close over your head.', 0, 0, 'cave', 0, -44, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-fall', 'north', 'the-sunk-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-fall', 'east', 'the-side-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rock-fall', 'south', 'the-cleared-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cleared-way', 'door', 'The Cleared Way', 'Past the fall the way is clean again, the light back, the flags level. Fallen stones have been moved to the walls on both sides and set down there in a row, carefully, all the same way, by something that did not use its hands.', 0, 0, 'cave', 0, -44, 10, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleared-way', 'north', 'the-rock-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cleared-way', 'south', 'the-south-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-south-road', 'door', 'The South Road', 'The straight way runs on south under its faint light, and the walls on both sides are cut with shallow niches at the height of your chest, empty, square, every one the same, a long row of them going away into the dark both ways.', 0, 0, 'cave', 0, -44, 11, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-road', 'north', 'the-cleared-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-road', 'south', 'the-near-sink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-road', 'west', 'the-south-cell', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-near-sink', 'door', 'The Near Sink', 'The way''s south end, where the dressed roof has a ragged hole broken through it and a rope hangs down out of the hole. Water has come down through it once and spread a skin of silt over the flags, and the stone''s light comes up dull through the silt.', 0, 0, 'cave', 0, -44, 12, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-near-sink', 'north', 'the-south-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-near-sink', 'south', 'the-sink-foot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sink-foot', 'door', 'The Sink Foot', 'The bottom of the Old Sink: a rough round shaft coming down through the roof, wet rock above and dressed stone below, and a heap of the river''s old gravel spread out across the floor under it, dark, covering the stone. The rope from above ends here, in a knot. The cold goes up the shaft past you.', 0, 0, 'cave', 0, -44, 13, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sink-foot', 'north', 'the-near-sink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sink-foot', 'up', 'the-old-sink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-west-door', 'door', 'The West Door', 'A doorway in the side of the straight way, square, its lintel a single stone, its jambs fitted to it without mortar. There is no door in it and no mark of a hinge. It was made to be walked through.', 0, 0, 'cave', 0, -45, 4, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-door', 'east', 'the-straight-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-door', 'west', 'the-pillared-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pillared-way', 'door', 'The Pillared Way', 'A way held up by square pillars of dressed stone, two and two, the roof flat on them, the faint light coming off every face. The pillars are worn at the height of your hip on the side toward the door, smooth, as if a great many hands had touched them going in.', 0, 0, 'cave', 0, -46, 4, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillared-way', 'east', 'the-west-door', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillared-way', 'west', 'the-pillar-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pillar-hall', 'door', 'The Pillar Hall', 'A hall of square pillars in rows, more of them than the light shows, so the hall seems to go on in every direction. The floor between them is very clean. The cold air comes up between the flags everywhere and the dust that blows along them is all going the same way, north.', 0, 0, 'cave', 0, -47, 4, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillar-hall', 'east', 'the-pillared-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillar-hall', 'north', 'the-north-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillar-hall', 'south', 'the-cracked-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-north-steps', 'door', 'The North Steps', 'Three broad steps go up out of the pillar hall, each a single stone, worn hollow in the middle. The air coming down them from the north is colder than any in the hall, and it smells of nothing, and it does not stop.', 0, 0, 'cave', 0, -47, 3, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-steps', 'south', 'the-pillar-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-north-steps', 'north', 'the-cold-passage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-passage', 'door', 'The Cold Passage', 'A narrow passage of dressed stone where the cold is so hard your breath smokes and frost lies white in the joints of the walls. The faint light of the stone is clearer here, as if the cold made it.', 0, 0, 'cave', 0, -47, 2, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-passage', 'south', 'the-north-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-passage', 'north', 'the-hum', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-hum', 'door', 'The Hum', 'A low sound comes from the walls here, a hum you feel more than hear, steady, rising very slowly and falling very slowly. Put a hand on the stone and it is in the stone. It is the sound the air makes, coming up through the joints.', 0, 0, 'cave', 0, -47, 1, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hum', 'south', 'the-cold-passage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hum', 'north', 'the-ante-room', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ante-room', 'door', 'The Ante-Room', 'A small square room before a doorway, its floor laid in a pattern: nine stones round one, and the one in the middle worn deep. Benches of stone run round the walls. Nobody has sat on them for longer than the oaks above have stood.', 0, 0, 'cave', 0, -47, 0, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ante-room', 'south', 'the-hum', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ante-room', 'west', 'the-ring-door', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ring-door', 'door', 'The Ring Door', 'A doorway with a lintel cut in a shallow curve, and on the curve, cut into the stone, a ring of nine small marks round one, the same as the floor of the room behind you. The air through the doorway is very cold and it is all coming one way, out.', 0, 0, 'cave', 0, -48, 0, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ring-door', 'east', 'the-ante-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ring-door', 'west', 'the-ring-of-nine', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-ring-of-nine', 'door', 'The Ring of Nine', 'A round chamber, the only round room in all this squared stone, and in its floor a ring of nine great flat stones set round a tenth, each the size of a table, each with its own joint round it. Nothing else stands in the room, and nothing has been left in it.', 0, 0, 'cave', 0, -49, 0, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ring-of-nine', 'east', 'the-ring-door', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ring-of-nine', 'down', 'the-under-steps', 'breathing-stone');
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-west-hall', 'door', 'The West Hall', 'A long hall going west from the cross, its floor worn by the track down the middle of it, wide and shallow. Along the walls the stone is scraped, low down, in long scratches, and the scratches are fresh and pale against the old grey.', 0, 0, 'cave', 0, -45, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-hall', 'east', 'the-cross-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-west-hall', 'west', 'the-brood-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-brood-way', 'door', 'The Brood Way', 'The track down the middle of the way is wet here, and the scratches along the walls are everywhere, crossing, at the height of your knee. Something has shed a skin on the floor, thin and grey and wrinkled, the shape of a thing with four legs and a long tail, the length of a dog.', 0, 0, 'cave', 0, -46, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brood-way', 'east', 'the-west-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brood-way', 'south', 'the-brood-nests', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brood-way', 'west', 'the-pale-walls', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-brood-nests', 'door', 'The Brood Nests', 'Hollows have been worn into the dressed floor of this room, shallow, each the length of a dog, a dozen of them, each with the stone polished smooth inside it by lying. Shed skins lie in some of them. They are all turned toward the west.', 0, 0, 'cave', 0, -46, 7, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brood-nests', 'north', 'the-brood-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cracked-flags', 'door', 'The Cracked Flags', 'The flags here have cracked across, every one of them, in the same direction, as if a great weight had been dragged over them once. The cold comes up through the cracks as well as the joints, hard, and the light from the stone comes up through them too.', 0, 0, 'cave', 0, -47, 5, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cracked-flags', 'north', 'the-pillar-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cracked-flags', 'south', 'the-pale-walls', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pale-walls', 'door', 'The Pale Walls', 'A hall of dressed stone with its walls scraped bare to a height above your head, the old grey surface gone, the stone under it pale and fresh. The track down the floor is deep here. It goes west, to a doorway at the far end, and the cold that comes out of it is the worst yet.', 0, 0, 'cave', 0, -47, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-walls', 'east', 'the-brood-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-walls', 'north', 'the-cracked-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-walls', 'west', 'the-sleepers-door', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sleepers-door', 'door', 'The Low Door', 'A doorway low and wide, much wider than a man needs, its jambs worn round at the height of your knee by something passing through it close against the stone on both sides at once. The light beyond is stronger. The stone there is not grey: it is white.', 0, 0, 'cave', 0, -48, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sleepers-door', 'east', 'the-pale-walls', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sleepers-door', 'west', 'the-worn-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-worn-hollow', 'door', 'The Worn Hollow', 'A long chamber floored with great white flags, and down the middle of it, worn into the stone, a hollow the shape of a lying body four times the length of a man, polished smooth as glass by lying. The cold air comes up through the joints all round the hollow and not through any other. Everything in this room faces the hollow.', 0, 0, 'cave', 0, -49, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-worn-hollow', 'east', 'the-sleepers-door', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-worn-hollow', 'west', 'the-cold-pit', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-worn-hollow', 'south', 'the-back-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-pit', 'door', 'The Cold Pit', 'Behind the hollow, a square pit in the floor, lined with dressed stone, going down into a dark that the stone''s light does not reach. The cold comes up out of it so hard it hurts. At the bottom of the light, the lining of the pit is scratched all over, from the inside.', 0, 0, 'cave', 0, -50, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-pit', 'east', 'the-worn-hollow', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-back-way', 'door', 'The Back Way', 'A narrow way leads out of the hollow''s room at its south end, low, the floor worn into a groove by the same track, going away south. Small bones lie in the groove, of grubbets and fish, and of something like a salamander, very large.', 0, 0, 'cave', 0, -49, 7, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-way', 'north', 'the-worn-hollow', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-way', 'south', 'the-groove', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-groove', 'door', 'The Groove', 'The track down the floor is a groove here as deep as your shin, worn into the dressed stone, and you walk in it because there is nowhere else to walk. The walls are close and scraped pale on both sides. The groove goes on south, toward water.', 0, 0, 'cave', 0, -49, 8, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-groove', 'north', 'the-back-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-groove', 'south', 'the-black-water-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-black-water-hall', 'door', 'The Black Water Hall', 'Water has come into the dressed stone here and stands over the floor, black and still and cold, a hand deep, hiding the stone and its light, so the room is dark. The groove goes in under the water and comes out the other side. Things move in the water, slowly.', 0, 0, 'cave', 0, -49, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-water-hall', 'north', 'the-groove', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-water-hall', 'east', 'the-pale-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pale-steps', 'door', 'The Pale Steps', 'Out of the water, the floor climbs in long shallow steps of white stone, the light back and bright on them, and the steps are wet where something came up them out of the water and went on, dragging.', 0, 0, 'cave', 0, -48, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-steps', 'west', 'the-black-water-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pale-steps', 'east', 'the-carved-rings', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-carved-rings', 'door', 'The Carved Rings', 'A long low hall of dressed stone, the roof so close you could put your hand flat on it, the light coming off it into your face. The track runs down the middle. Along the walls, set into them in a row, there are flat stones carved with rings, nine round one, again and again.', 0, 0, 'cave', 0, -47, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-carved-rings', 'west', 'the-pale-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-carved-rings', 'east', 'the-south-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-south-hall', 'door', 'The South Hall', 'A wide hall at the south of the dressed stone, square, its roof held up by four pillars. Old bones lie at the foot of the pillars in heaps, small dark bones of a people smaller than the holding''s, packed close in no order, and under the heaps the floor''s light shows through.', 0, 0, 'cave', 0, -46, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-hall', 'west', 'the-carved-rings', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-hall', 'south', 'the-bone-pillars', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-bone-pillars', 'door', 'The Bone Pillars', 'More bones, and here they have been laid against the pillars in courses, built up like walls, careful, a people''s dead put up round the pillars one on another. Their skulls all face the same way, toward the west. The cold air comes up through the joints under them.', 0, 0, 'cave', 0, -46, 10, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-pillars', 'north', 'the-south-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bone-pillars', 'east', 'the-quiet-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-quiet-way', 'door', 'The Quiet Way', 'A short way of dressed stone, the walls plain, nothing in it, the light even. It is the only place down here where the air does not move at all. Your breathing is the only sound.', 0, 0, 'cave', 0, -45, 10, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quiet-way', 'west', 'the-bone-pillars', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quiet-way', 'south', 'the-south-cell', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-south-cell', 'door', 'The South Cell', 'A square cell off the south road, its doorway narrow, its floor one single stone, the light coming up out of it white and even. In the middle of the stone there is a hand-mark, a palm and five fingers, sunk into the stone as if the stone had been soft once when a hand was laid on it. The hand is small.', 0, 0, 'cave', 0, -45, 11, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-cell', 'north', 'the-quiet-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-south-cell', 'east', 'the-south-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-east-hall', 'door', 'The East Hall', 'A hall going east from the cross, its walls lined with shallow niches at the height of your chest, every one empty, the light coming out of the backs of them. Something was kept in each. The dust in each has the clean square print of it, gone.', 0, 0, 'cave', 0, -43, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-hall', 'west', 'the-cross-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-hall', 'east', 'the-pillared-east', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-pillared-east', 'door', 'The Pillared East', 'A hall of pillars on the east side, as tall as the ones on the west, and here the pillars have been cut into at the height of a man''s shoulder, all of them, with pick-marks, as if someone had tried each pillar in turn to see what it was made of. They are made of stone all the way through.', 0, 0, 'cave', 0, -42, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillared-east', 'west', 'the-east-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pillared-east', 'east', 'the-east-way', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-east-way', 'door', 'The East Way', 'A straight way going north and south along the east of the stone, plainer than the rest, the walls undressed in places, as if it were the back of something. The air moves along it northward and the light lies on it thin.', 0, 0, 'cave', 0, -41, 6, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-way', 'west', 'the-pillared-east', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-way', 'north', 'the-buried-hall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-way', 'south', 'the-sheet-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-buried-hall', 'door', 'The Buried Hall', 'The roof has come down over the whole of this hall, slowly, by the look of it, sagging in one piece before it broke, and the hall is half full of rock and dark where the rock lies. A way through it has been scraped out, low, wide, at the height of a lying body.', 0, 0, 'cave', 0, -41, 5, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-buried-hall', 'south', 'the-east-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-buried-hall', 'north', 'the-cold-cell', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cold-cell', 'door', 'The Cold Cell', 'A square cell where the cold coming up through the floor has hung frost all over the walls in feathers a finger long. The light comes through the frost blue-white. Something has lain on the floor and melted a shape into the frost, and the frost has not yet grown back over it.', 0, 0, 'cave', 0, -41, 4, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-cell', 'south', 'the-buried-hall', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sheet-water', 'door', 'The Sheet Water', 'Water seeps in through the joints of the east wall here and runs down it and across the floor in a sheet as thin as glass, and the stone''s light comes up through it rippling. It runs one way across the floor, west, uphill.', 0, 0, 'cave', 0, -41, 7, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheet-water', 'north', 'the-east-way', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sheet-water', 'south', 'the-drowned-flags', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-drowned-flags', 'door', 'The Drowned Flags', 'The water lies deep here over the floor, over your knee, still and black, and the light of the stone does not come through it. It is dark. You feel the flags under your feet, and the joints between them, and the cold coming up through the water from them.', 0, 0, 'cave', 0, -41, 8, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-flags', 'north', 'the-sheet-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-flags', 'south', 'the-east-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-east-road', 'door', 'The East Road', 'The way out of the water, the floor rising dry again and the light coming back up out of it. A short road of dressed stone joins the east way to the straight way, its flags laid in a herringbone, each one fitted to the next so close that the herringbone is the only sign there are joints at all.', 0, 0, 'cave', 0, -41, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-road', 'north', 'the-drowned-flags', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-road', 'west', 'the-east-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-east-steps', 'door', 'The East Steps', 'The herringbone road ends at two broad steps down to the straight way. On the top step someone has scratched a mark with a knife point: a ring, with a line through it. The scratch is new against the stone.', 0, 0, 'cave', 0, -42, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-steps', 'east', 'the-east-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-east-steps', 'west', 'the-side-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-side-arch', 'door', 'The Side Arch', 'An arch opens in the east wall of the straight way here, low and round-headed, the only curve in the wall for its whole length. Its keystone is cut with a ring of nine small marks round one. Through it, two broad steps go up to a road laid in herringbone.', 0, 0, 'cave', 0, -43, 9, -3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-side-arch', 'west', 'the-rock-fall', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-side-arch', 'east', 'the-east-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-under-steps', 'door', 'The Under-Steps', 'Steps go down under the tilted stone, narrow and steep, cut from the living rock and worn hollow in the middle by feet much smaller than yours. The cold comes up them so hard it pushes. At the top the edge of the great stone stands up against the dark.', 0, 0, 'cave', 0, -48, 1, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-steps', 'up', 'the-ring-of-nine', 'breathing-stone');
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-steps', 'south', 'the-low-gallery-under', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-low-gallery-under', 'door', 'The Low Gallery', 'A gallery cut low, for people shorter than you, so you go along it stooping, the roof brushing your hair. The walls are smooth and dark and give no light. Along both of them at the height of your waist runs a carved band of rings, nine round one, over and over, with no end and no beginning.', 0, 0, 'cave', 0, -48, 2, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-gallery-under', 'north', 'the-under-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-gallery-under', 'east', 'the-shelved-room', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-low-gallery-under', 'south', 'the-worn-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-shelved-room', 'door', 'The Shelved Room', 'A small room with shelves cut out of the rock on three walls, and things on the shelves: bowls of black stone, thin as a leaf; little figures of something with four legs and a long tail, carved in white stone, dozens of them, every one lying flat; a heap of rings of bone. Dust lies on all of it like snow.', 0, 0, 'cave', 0, -47, 2, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelved-room', 'west', 'the-low-gallery-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shelved-room', 'east', 'the-box-chamber', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-box-chamber', 'door', 'The Box Chamber', 'A square chamber with nothing in it but a box: a long box of the same flat dressed stone as the floors above, its lid a single slab, a keyhole cut through the slab no bigger than your little finger. The box stands on the floor exactly in the middle of the room. Everything else down here was put by hand. This was put first.', 0, 0, 'cave', 0, -46, 2, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-box-chamber', 'west', 'the-shelved-room', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-worn-floor', 'door', 'The Worn Floor', 'A room where the floor is worn into hollows by kneeling: rows of them, each a pair of shallow dips side by side, all facing the far wall. The far wall is blank. Cold comes off it, not up through the floor, as if it were the outside of something.', 0, 0, 'cave', 0, -48, 3, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-worn-floor', 'north', 'the-low-gallery-under', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-worn-floor', 'west', 'the-faces-down', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-worn-floor', 'south', 'the-open-joint', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-faces-down', 'door', 'The Faces Down', 'The older people''s dead are here, a few of them, laid out on the floor in a row, each face down on the stone with its arms at its sides and its hands flat. Small people. They were laid like that on purpose, all of them, to face down. Nothing has disturbed them. Nothing comes here.', 0, 0, 'cave', 0, -49, 3, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-faces-down', 'east', 'the-worn-floor', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-open-joint', 'door', 'The Open Joint', 'The last room. The floor is two great stones with a joint between them wider than any above, a hand''s width, running wall to wall, and out of it the cold comes up in a flood, steady, silent, forever. Below the joint there is no light and no bottom to see. Round its edges, the stone is worn smooth by hands, as if a great many people had knelt here and pressed down on it.', 0, 0, 'cave', 0, -48, 4, -4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-open-joint', 'north', 'the-worn-floor', NULL);
